import{_ as o,o as t,c as n,a0 as a}from"./chunks/framework.ChlVJx0I.js";const p=JSON.parse('{"title":"The Tool row header names the Tool origin","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0045-the-tool-row-header-names-the-tool-origin.md","filePath":"adr/0045-the-tool-row-header-names-the-tool-origin.md","lastUpdated":1792392726000}'),s={name:"adr/0045-the-tool-row-header-names-the-tool-origin.md"};function i(r,e,l,d,h,c){return t(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="the-tool-row-header-names-the-tool-origin" tabindex="-1">The Tool row header names the Tool origin <a class="header-anchor" href="#the-tool-row-header-names-the-tool-origin" aria-label="Permalink to &quot;The Tool row header names the Tool origin&quot;">​</a></h1><p>ADR 0038 drew a header carrying the tool name and nothing else. Issue #154 widens it: the header now carries the tool name and its Origin tag, so a row says who supplied its tool - <code>built-in</code> for pi&#39;s own tool, <code>mcp</code> for an MCP server&#39;s tool, and the extension&#39;s own name for an extension&#39;s tool. The split between pi and an extension comes from pi&#39;s own per-tool source metadata, but that metadata reports the tools of pi&#39;s built-in MCP extension as built-in too, so the MCP case can only come from pi&#39;s own <code>mcp__&lt;server&gt;__&lt;tool&gt;</code> name rule, which the header already parses for its <code>server/tool</code> name.</p><p><strong>Considered options</strong>: a static list of built-in tool names breaks on every pi rename and can never name an extension; naming the package instead of the extension says <code>pi-extensions</code> on most of this package&#39;s rows while never saying which of its extensions a tool came from, and a git-installed package path carries no package-name segment for the existing <code>/tools</code> rule to find, which is why <code>/tools</code> today labels every directory-style extension <code>index</code>; an SDK origin of its own was left out, because that origin only appears in embedded runs, which never draw a Tool row in the TUI this extension serves.</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>One classifier answers the fact, and the two surfaces show it differently on purpose: the transcript names the Tool origin on every row, while the <code>/tools</code> list keeps its compact convention of no tag for a built-in. Naming the extension rather than the package also changes <code>/tools</code>: a directory-style extension of a git package is labeled by its own name instead of <code>index</code>.</li><li>The tag is all or nothing. A row too narrow for it loses the tag and its separator and draws exactly the line ADR 0038 described, so the ladder that spends the rule first, then the name, is unchanged underneath.</li><li>A row whose tool pi does not report - an MCP row in a resumed session before its server connected - gets the name rule and nothing else. No tag means the origin is unknown, never a guess, which is why built-ins are tagged rather than left silent.</li><li>The origin of one tool name is read once and memoized for the life of the extension instance. A reload re-runs every extension factory and re-reads the registry, so the only stale case is one tool name claimed by two extensions inside one session, which pi already resolves by load order.</li></ul>',5)])])}const g=o(s,[["render",i]]);export{p as __pageData,g as default};
